"use client";

/**
 * Gradient field: a few large, soft blobs of the primary and accent tones drift
 * slowly over the page colour, like light through frosted glass. A calm bed to
 * set titles or product shots on.
 *
 * Written by Better Design. The motion is periodic over `loopFrames`, so the
 * last frame meets the first and the background loops without a seam.
 */
import type { ReactNode } from "react";
import { AbsoluteFill, random, useCurrentFrame } from "remotion";
import { shiftHue, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

export interface GradientFieldProps {
  /** Drawn on top of the field. */
  children?: ReactNode;
  /** Blob colours. Defaults to tones of the theme's primary and accent. */
  colors?: string[];
  /** Frames for one full cycle of the drift. The field loops at this length. */
  loopFrames?: number;
  /** Strength of the blobs, 0 to 1. Lower is quieter. */
  intensity?: number;
  /** Changes the blob layout while keeping it deterministic. */
  seed?: string;
  theme?: Partial<VideoTheme>;
}

const TAU = Math.PI * 2;


/** Slow drifting soft blobs of the theme's colours, looping seamlessly, with children on top. */
export function GradientField({ children, colors, loopFrames = 180, intensity = 0.7, seed = "field", theme: themeOverride }: GradientFieldProps) {
  const t = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const phase = (frame / loopFrames) * TAU;
  // Hue neighbours of the primary, plus the accent wash for a quieter patch.
  const palette = colors ?? [t.primary, shiftHue(t.primary, 40), t.accent, shiftHue(t.primary, -20)];

  const blobs = palette.map((color, i) => {
    const r = (k: string) => random(`${seed}-${i}-${k}`);
    // Each blob orbits its home on a small ellipse, a whole number of times per loop.
    const homeX = 0.15 + r("x") * 0.7;
    const homeY = 0.15 + r("y") * 0.7;
    const turns = r("dir") > 0.5 ? 1 : -1;
    const start = r("p") * TAU;
    const x = homeX + Math.cos(phase * turns + start) * (0.08 + r("ax") * 0.08);
    const y = homeY + Math.sin(phase * turns + start) * (0.06 + r("ay") * 0.06);
    const size = 900 + r("s") * 500;
    const breathe = 1 + Math.sin(phase * 2 + start) * 0.06;
    return { color, x, y, size: size * breathe };
  });

  return (
    <AbsoluteFill style={{ background: t.background, overflow: "hidden" }}>
      <AbsoluteFill style={{ filter: "blur(80px)" }}>
        {blobs.map((b, i) => (
          <div
            key={i}
            style={{
              position: "absolute",
              left: `${b.x * 100}%`,
              top: `${b.y * 100}%`,
              width: b.size,
              height: b.size,
              marginLeft: -b.size / 2,
              marginTop: -b.size / 2,
              borderRadius: "50%",
              background: `radial-gradient(circle, ${withAlpha(b.color, intensity)} 0%, ${withAlpha(b.color, intensity * 0.35)} 45%, ${withAlpha(b.color, 0)} 70%)`,
            }}
          />
        ))}
      </AbsoluteFill>
      {/* A faint wash of the page colour keeps text on top readable. */}
      <AbsoluteFill style={{ background: `radial-gradient(ellipse at 50% 50%, ${withAlpha(t.background, 0.25)} 0%, ${withAlpha(t.background, 0)} 70%)` }} />
      {children ? <AbsoluteFill>{children}</AbsoluteFill> : null}
    </AbsoluteFill>
  );
}
